package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_containsAny_TriageGen0Test {

    @Test
    public void testContainsAny_NullCharSequence() {
        assertFalse(StringUtils.containsAny(null, new char[]{'a'}));
    }

    @Test
    public void testContainsAny_EmptyCharSequence() {
        assertFalse(StringUtils.containsAny("", new char[]{'a'}));
    }

    @Test
    public void testContainsAny_NullSearchChars() {
        assertFalse(StringUtils.containsAny("abc", null));
    }

    @Test
    public void testContainsAny_EmptySearchChars() {
        assertFalse(StringUtils.containsAny("abc", new char[]{}));
    }

    @Test
    public void testContainsAny_NoMatch() {
        assertFalse(StringUtils.containsAny("abc", new char[]{'d', 'e', 'f'}));
    }

    @Test
    public void testContainsAny_SingleMatch() {
        assertTrue(StringUtils.containsAny("abc", new char[]{'b'}));
    }

    @Test
    public void testContainsAny_MultipleMatches() {
        assertTrue(StringUtils.containsAny("abc", new char[]{'a', 'c'}));
    }

    @Test
    public void testContainsAny_MatchAtStart() {
        assertTrue(StringUtils.containsAny("abc", new char[]{'a'}));
    }

    @Test
    public void testContainsAny_MatchAtEnd() {
        assertTrue(StringUtils.containsAny("abc", new char[]{'c'}));
    }

    @Test
    public void testContainsAny_BMP_Match() {
        // Test character in Basic Multilingual Plane
        assertTrue(StringUtils.containsAny("hello", new char[]{'e'}));
    }

    @Test
    public void testContainsAny_SupplementaryCharacter_FullMatch() {
        // U+1F600 (Grinning Face) is represented by surrogate pair: \uD83D\uDE00
        char[] smiley = {'\uD83D', '\uDE00'};
        String text = "Hello \uD83D\uDE00!";
        assertTrue(StringUtils.containsAny(text, smiley));
    }

    @Test
    public void testContainsAny_SupplementaryCharacter_PartialMatch_Fail() {
        // High surrogate matches but next char in searchChars is different
        char[] partialSmiley = {'\uD83D', '\uDE01'};
        String text = "Hello \uD83D\uDE00!";
        // The loop finds \uD83D, but searchChars[j+1] (\uDE01) != cs.charAt(i+1) (\uDE00)
        assertFalse(StringUtils.containsAny(text, partialSmiley));
    }

    @Test
    public void testContainsAny_SupplementaryCharacter_EdgeCase_EndOfString() {
        // High surrogate is at the very end of the string (should not happen in valid UTF-16, but testing logic)
        char[] smiley = {'\uD83D', '\uDE00'};
        String text = "End \uD83D";
        // i < csLastIndex will be false, so it hits the 'else' (BMP logic)
        // However, the code logic: if (i < csLastIndex && j < searchLastIndex && ch <= MAX_HIGH_SURROGATE)
        // If i is the last index, it goes to the else block.
        assertFalse(StringUtils.containsAny(text, smiley));
    }

    @Test
    public void testContainsAny_SupplementaryCharacter_EdgeCase_EndOfSearchChars() {
        // High surrogate is at the end of searchChars
        char[] partialSmiley = {'\uD83D'};
        String text = "Hello \uD83D\uDE00!";
        // j < searchLastIndex will be false, goes to else block, returns true because \uD83D is a char
        assertTrue(StringUtils.containsAny(text, partialSmiley));
    }

    @Test
    public void testContainsAny_HighSurrogate_AsBMP() {
        // Testing the branch where ch <= Character.MAX_HIGH_SURROGATE is true 
        // but the logic falls into the 'else' due to index bounds.
        char[] search = {'\uD83D'};
        String cs = "\uD83D"; 
        // csLastIndex is 0. i is 0. i < csLastIndex is false.
        assertTrue(StringUtils.containsAny(cs, search));
    }
}
